<template><main class="experience-admin"><header><div><p class="eyebrow">TrastTravel</p><h1>Customer experience</h1><p>Configure arrival locations and the review email sent after a tour.</p></div><button class="primary" :disabled="saving" @click="saveSettings">{{ saving?'Saving…':'Save settings' }}</button></header>
<section class="panel"><h2>Post-tour review invitation</h2><div class="grid"><label><span>Enabled</span><input v-model="settings.reviewEnabled" type="checkbox"></label><label><span>Delay after tour (hours)</span><input v-model.number="settings.reviewDelayHours" min="0" type="number"></label><label class="wide"><span>Eligible booking statuses</span><input v-model="settings.eligibleStatuses" type="text"></label><label class="wide"><span>Review URL</span><input v-model="settings.reviewUrl" type="url" placeholder="https://..."></label><label class="wide"><span>Email subject</span><input v-model="settings.reviewSubject" type="text"></label><label class="wide"><span>Email message</span><textarea v-model="settings.reviewBody" rows="5"></textarea></label><label><span>Button text</span><input v-model="settings.reviewButtonText" type="text"></label></div></section>
<section class="panel"><h2>Arrival or pickup selection</h2><div class="grid"><label><span>Enabled</span><input v-model="settings.arrivalEnabled" type="checkbox"></label><label><span>Required</span><input v-model="settings.arrivalRequired" type="checkbox"></label><label><span>Field label</span><input v-model="settings.arrivalLabel"></label><label class="wide"><span>Help text</span><input v-model="settings.arrivalHelp"></label></div><div class="toolbar"><h3>Locations</h3><button @click="editLocation()">Add location</button></div><div class="locations"><article v-for="location in locations" :key="location.id"><div><strong>{{ location.name }}</strong><small>{{ location.type }} · {{ location.active?'Active':'Inactive' }}</small><p>{{ location.instructions }}</p></div><div><button @click="editLocation(location)">Edit</button><button @click="removeLocation(location.id)">Delete</button></div></article><p v-if="!locations.length">No locations configured.</p></div></section>
<div v-if="editing" class="modal" role="dialog"><form class="modal-card" @submit.prevent="saveLocation"><h2>{{ draft.id?'Edit':'Add' }} location</h2><label><span>Name</span><input v-model="draft.name" required></label><label><span>Type</span><select v-model="draft.type"><option>CRUISE_PORT</option><option>HOTEL</option><option>AIRPORT</option><option>OTHER</option></select></label><label><span>Instructions</span><textarea v-model="draft.instructions"></textarea></label><label><span>Tour ID (blank means all tours)</span><input v-model="draft.tourReference"></label><label><span>Order</span><input v-model.number="draft.sortOrder" type="number"></label><label><span>Active</span><input v-model="draft.active" type="checkbox"></label><footer><button type="button" @click="editing=false">Cancel</button><button class="primary">Save</button></footer></form></div><p v-if="message" class="message">{{ message }}</p></main></template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';
const settings=reactive<any>({reviewEnabled:false,reviewDelayHours:24,eligibleStatuses:'CONFIRMED,PAID,COMPLETED',reviewSubject:'How was your tour?',reviewBody:'Thank you for visiting us.',reviewButtonText:'Leave a review',reviewUrl:'',arrivalEnabled:true,arrivalRequired:true,arrivalLabel:'Arrival or pickup location',arrivalHelp:''});const locations=ref<any[]>([]),saving=ref(false),message=ref(''),editing=ref(false);const draft=reactive<any>({});
async function api(url:string,init?:RequestInit){const r=await fetch(url,{credentials:'include',headers:{'Content-Type':'application/json',...(init?.headers||{})},...init});if(!r.ok)throw new Error(await r.text());return r.status===204?null:r.json()}
async function load(){Object.assign(settings,await api('/api/admin/travel/customer-experience/settings'));locations.value=await api('/api/admin/travel/customer-experience/arrival-locations')}
async function saveSettings(){saving.value=true;try{Object.assign(settings,await api('/api/admin/travel/customer-experience/settings',{method:'PUT',body:JSON.stringify(settings)}));message.value='Settings saved.'}catch(e:any){message.value=e.message}finally{saving.value=false}}
function editLocation(v:any={name:'',type:'OTHER',instructions:'',tourReference:'',active:true,sortOrder:0}){Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,v);editing.value=true}
async function saveLocation(){const url=draft.id?`/api/admin/travel/customer-experience/arrival-locations/${draft.id}`:'/api/admin/travel/customer-experience/arrival-locations';await api(url,{method:draft.id?'PUT':'POST',body:JSON.stringify(draft)});editing.value=false;await load()}
async function removeLocation(id:number){if(confirm('Delete this location?')){await api(`/api/admin/travel/customer-experience/arrival-locations/${id}`,{method:'DELETE'});await load()}}
onMounted(load);
</script>
<style scoped>.experience-admin{display:grid;gap:1.25rem;padding:1.25rem;max-width:1120px;margin:auto}.experience-admin header,.toolbar{display:flex;align-items:center;justify-content:space-between;gap:1rem}.eyebrow{font-size:.75rem;text-transform:uppercase;letter-spacing:.12em}.panel,.modal-card{background:var(--panel-bg,#fff);border:1px solid var(--border-color,#e4e7ec);border-radius:.75rem;padding:1.25rem}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.wide{grid-column:1/-1}label{display:grid;gap:.35rem}input,select,textarea{width:100%;padding:.65rem;border:1px solid var(--border-color,#d0d5dd);border-radius:.5rem;background:inherit;color:inherit}.locations article{display:flex;justify-content:space-between;gap:1rem;padding:.8rem 0;border-top:1px solid var(--border-color,#e4e7ec)}small{display:block}.primary{background:var(--primary,#4f46e5);color:#fff;border:0;border-radius:.5rem;padding:.7rem 1rem}.modal{position:fixed;inset:0;background:#0008;display:grid;place-items:center;padding:1rem;z-index:100}.modal-card{width:min(560px,100%);display:grid;gap:1rem}.modal-card footer{display:flex;justify-content:flex-end;gap:.75rem}@media(max-width:720px){.grid{grid-template-columns:1fr}.experience-admin header,.toolbar,.locations article{align-items:stretch;flex-direction:column}.wide{grid-column:auto}}</style>
